import { mapState } from 'vuex'
import {
  seckillTimeList,
  seckillTimeCreate,
  seckillSetStatus
} from "@/api/marketing";
import Setting from "@/setting";
export default {
  name: 'config',
  data () {
    return {
      grid: {
        xl: 7,
        lg: 7,
        md: 12,
        sm: 24,
        xs: 24
      },
      formValidate: {
        status: '',
        page: 1,
        limit: 20
      },
      total: 0,
      tabList: [],
      columns1: [
        {
          title: "ID",
          key: "id",
          width: 80,
        },
        {
          title: "活动名称",
          key: "title",
          minWidth: 170,
        },
        {
          title: "开始时间",
          key: "start_time",
          minWidth: 150,
        },
        {
          title: "结束时间",
          key: "end_time",
          minWidth: 150,
        },
        {
          title: "幻灯片",
          slot: "pic",
          minWidth: 150,
        },
        {
          title: "描述",
          key: "describe",
          minWidth: 240,
        },
        {
          title: "是否可用",
          slot: "status",
          minWidth: 100,
        },
        {
          title: "操作",
          slot: "action",
          minWidth: 110,
          fixed: 'right'
        },
      ],
      loading: false
    }
  },
  computed: {
    ...mapState('admin/layout', [
      'isMobile'
    ]),
    labelWidth () {
      return this.isMobile ? undefined : 96;
    },
    labelPosition () {
      return this.isMobile ? 'top' : 'right';
    }
  },
  mounted () {
    this.getList();
  },
  methods: {
    // 添加表单
    groupAdd () {
      this.$modalForm(seckillTimeCreate(0)).then(() => this.getList());
    },
    // 编辑表单
    edit (row) {
      this.$modalForm(seckillTimeCreate(row.id)).then(() => this.getList());
    },
    // 列表
    getList () {
      this.loading = true
      seckillTimeList(this.formValidate).then(res => {
        let data = res.data
        this.tabList = data.list
        this.total = data.count
        this.loading = false
      }).catch(res => {
        this.loading = false
        this.$Message.error(res.msg)
      })
    },
    pageChange (index) {
      this.formValidate.page = index
      this.getList()
    },
    // 表格搜索
    userSearchs () {
      this.formValidate.page = 1
      this.getList()
    },
    // 修改是否显示
    onchangeIsShow (row) {
      seckillSetStatus(row).then(async res => {
        this.$Message.success(res.msg)
        this.getList()
      }).catch(res => {
        this.$Message.error(res.msg)
      })
    },
    // 删除
    del(row, tit, num) {
      let delfromData = {
        title: tit,
        num: num,
        url: `/marketing/seckill/time/${row.id}`,
        method: "DELETE",
        ids: "",
      };
      this.$modalSure(delfromData)
          .then((res) => {
            this.$Message.success(res.msg);
            this.tabList.splice(num, 1);
            if (!this.tabList.length) {
              this.formValidate.page =
                  this.formValidate.page == 1 ? 1 : this.formValidate.page - 1;
            }
            this.getList();
          })
          .catch((res) => {
            this.$Message.error(res.msg);
          });
    }
  }
}
